$target = 'C:\workspace\zveris\ui\static\index.html'
if (Test-Path -LiteralPath $target) { throw 'Failas jau atsirado - sustoju, kad neperrasytum' }
New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(''))
Get-Item -LiteralPath $target | Select-Object FullName,Length,LastWriteTime | Format-List
Get-FileHash -LiteralPath $target -Algorithm SHA256 | Select-Object Hash
